import { after } from 'next/server';

export default function WelcomePage() {
  // Use `after` to schedule work after the response is sent.
  // This ensures the logging doesn't block the response.
  after(async () => {
    // Simulate logging to an external analytics service
    console.log('Logging page view...');
    await new Promise((resolve) => setTimeout(resolve, 1000));
    console.log('Page view logged successfully!');
  });

  return (
    <div className="flex flex-col items-center justify-center min-h-screen py-2">
      <main className="flex flex-col items-center justify-center w-full flex-1 px-20 text-center">
        <h1 className="text-6xl font-bold">
          Welcome to the Next.js App!
        </h1>
        <p className="mt-3 text-2xl">
          Your visit has been logged in the background.
        </p>
      </main>
    </div>
  );
}

